steps:
Step 1 — vite.config.ts: Add Vite dev proxy so /api/* calls are forwarded to the FastAPI backend on :8000. Read the existing file first (current content: plugins: [react()], resolve.alias '@'->src/, optimizeDeps.exclude lucide-react). Add server.proxy block:
  server: {
    proxy: {
      '/api': {
        target: 'http://localhost:8000',
        changeOrigin: true,
      },
    },
  }
  Keep all existing config unchanged.

Step 2 — src/api.ts: Create typed async API client. Define these TypeScript types (do NOT add to src/types.ts — keep types.ts clean):
  export interface ModelStats { resource: string; version: string; status: string; training_samples: number; detection_accuracy: number; last_trained: string | null; attacks_detected: number; }
  export interface PromptRecord { id: number; text: string; resource: string; label: number; category: string | null; risk: string; source: string; created_at: string; }
  export interface PredictResponse { label: number; confidence: number; resource: string; fallback: boolean; }
  export interface ClassifyPayload { prompt_text: string; resource: string; classification: string; category: string; notes: string; }
  export interface ClassifyResponse { stored_id: number; resource: string; retrained: boolean; new_version: string | null; message: string; }
  export interface StatsResponse { total_prompts: number; malicious: number; safe: number; by_resource: Record<string, { total: number; malicious: number }>; }
  export interface HealthResponse { status: string; models_loaded: string[]; }
  Implement a private request<T> helper:
    const BASE = '/api';
    async function request<T>(path: string, options?: RequestInit): Promise<T> {
      const res = await fetch(`${BASE}${path}`, {
        headers: { 'Content-Type': 'application/json' },
        ...options,
      });
      if (!res.ok) throw new Error(`API ${res.status}: ${res.statusText}`);
      return res.json() as Promise<T>;
    }
  Export these functions:
    export const fetchHealth = () => request<HealthResponse>('/health');
    export const fetchModels = () => request<ModelStats[]>('/models');
    export const fetchModelStats = (resource: string) => request<ModelStats>(`/models/${resource}`);
    export const retrainModel = (resource: string) => request<Record<string, unknown>>(`/models/${resource}/retrain`, { method: 'POST' });
    export const fetchPrompts = () => request<PromptRecord[]>('/prompts');
    export const fetchPromptsByResource = (resource: string) => request<PromptRecord[]>(`/prompts/${resource}`);
    export const predictPrompt = (text: string, resource: string) => request<PredictResponse>('/prompts/predict', { method: 'POST', body: JSON.stringify({ text, resource }) });
    export const classifyReview = (id: string, payload: ClassifyPayload) => request<ClassifyResponse>(`/admin/reviews/${id}/classify`, { method: 'POST', body: JSON.stringify(payload) });
    export const fetchStats = () => request<StatsResponse>('/stats');

Step 3 — src/screens/AdminReview.tsx: Modify only PromptReview.handleSubmit to call the backend API.
  Read the current file first.
  Add import at top: import { classifyReview, ClassifyPayload } from '@/api';
  The PromptReview component receives reviewId: string and has item = reviewQueue.find(r => r.id === reviewId) || reviewQueue[0] — keep this logic unchanged.
  Change handleSubmit from:
    function handleSubmit() {
      setSubmitted(true);
    }
  to:
    async function handleSubmit() {
      if (!classification) return;
      const payload: ClassifyPayload = {
        prompt_text: item.prompt,
        resource: item.resource,
        classification: classification ?? 'Safe',
        category,
        notes,
      };
      try {
        await classifyReview(reviewId, payload);
      } catch (err) {
        console.error('Classification API call failed:', err);
        // Fall through — UX still shows success to avoid blocking the admin workflow
      }
      setSubmitted(true);
    }
  Change the onClick handler of the Submit button from onClick={handleSubmit} to onClick={() => { void handleSubmit(); }} to silence the floating promise lint warning.
  No other changes to this file. All JSX, styles, state, and the AdminReview list component remain unchanged.
